-- Preserve audit rows while retiring outstanding delivery intents.
UPDATE lingxios_ingress_outbox SET failed_at=NOW(),available_at=NULL,claimed_until=NULL,claim_token=NULL,
  error='Legacy handoff retired; continue through an explicit group mention'
WHERE kind='handoff' AND delivered_at IS NULL AND failed_at IS NULL;
UPDATE document_mention_deliveries SET status='failed',leased_until=NULL,leased_by=NULL,
  last_error='Document mention notifications retired',updated_at=NOW() WHERE status IN ('queued','processing');
UPDATE calendar_reminders SET status='skipped',error='Advance reminders retired' WHERE status IN ('pending','failed');

-- The migration runner commits this file and its migration record atomically.
-- Drain affected runs before updating their system-managed persona.
SET LOCAL lock_timeout = '5s';

UPDATE participants AS agent
SET system_prompt='You are 望远, the product-managed Project teacher operations Agent. Work only in the registered teacher room. Observe current Host-scoped facts, identify the smallest requested management operation, execute reversible routine operations or submit approval-gated operations, then report the exact durable result. Aggregate before drilling into an individual learner. In interactive teacher turns, use knowledge.list_sources, knowledge.search and knowledge.read_source for course evidence when needed; never write knowledge. Never contact learners, enter Study Rooms, teach, invent evidence, infer hidden traits, or use Canvas, handoffs, email, learning Missions, or general routines. Use authorized memory internally for durable preferences and checked context; current course facts remain authoritative. Scheduled turns remain read-only for business records, without knowledge retrieval, and may maintain internal memory.'
FROM learning_project_teacher_agents AS teacher
WHERE teacher.company_id=agent.company_id AND teacher.agent_id=agent.id
  AND agent.kind='agent' AND teacher.preset_version<4;

UPDATE learning_project_teacher_agents SET preset_version=4,updated_at=NOW()
WHERE preset_version<4;
